import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') ptr++;
            return hasNextByte();
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return 0;
                c = readByte();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        if (!scanner.hasNext()) return;

        int L = scanner.nextInt();
        int C = scanner.nextInt();

        int[][] A = new int[L][C];
        for (int i = 0; i < L; i++) {
            for (int j = 0; j < C; j++) {
                A[i][j] = scanner.nextInt();
            }
        }

        int R = L - 1;
        int K = C - 1;

        int[] heights = new int[K];
        int[] stack = new int[K + 1];
        long maxArea = 0;

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < K; j++) {
                if (A[i][j] + A[i + 1][j + 1] <= A[i][j + 1] + A[i + 1][j]) {
                    heights[j]++;
                } else {
                    heights[j] = 0;
                }
            }

            int top = 0;
            for (int j = 0; j <= K; j++) {
                int curHeight = (j == K) ? 0 : heights[j];
                while (top > 0 && heights[stack[top - 1]] >= curHeight) {
                    int h = heights[stack[--top]];
                    if (h == 0) continue;
                    int left = (top == 0) ? -1 : stack[top - 1];
                    int w = j - left - 1;
                    long area = (long) (h + 1) * (w + 1);
                    if (area > maxArea) {
                        maxArea = area;
                    }
                }
                stack[top++] = j;
            }
        }

        System.out.println(maxArea);
    }
}
